// Two creation paths: describe a Slice, or provide a project's representative slice.
document.querySelector('[data-mode="template"]').remove();modes.classList.add('two-modes');
generateMode.innerHTML='<strong>✦ 描述生成</strong><span>描述想法，附上图片或文档</span>';
document.querySelector('[data-mode="html"]').innerHTML='<strong>↥ 上传项目</strong><span>从文件展示，或自定义 Slice</span>';
document.querySelector('.prompt-examples').hidden=true;document.querySelector('#generation-kind').closest('label').hidden=true;document.querySelector('#generation-kind').value='auto';
document.querySelector('#slice-prompt').placeholder='描述你想让大家看到什么、做什么。例如：用我的旅行照片做一个目的地选择卡。';
const modelField=document.createElement('label');modelField.className='model-field';modelField.innerHTML='算力模型 / API <select id="compute-model"><option value="local">本地演示 · 无需 API</option><option value="fast">快速模型 · API 配置示例</option><option value="standard">标准模型 · API 配置示例</option><option value="reasoning">推理模型 · API 配置示例</option></select><small id="model-status">本地生成可用。真实 API 尚未连接；接入后在这里选择预先配置的模型。</small>';document.querySelector('#generate-slice').before(modelField);
document.querySelector('.generation-note').textContent='当前按描述套用交互规则，不调用 AI，也不识别图片。';
const computeModel=document.querySelector('#compute-model');computeModel.onchange=()=>{const local=computeModel.value==='local';document.querySelector('#model-status').textContent=local?'本地生成可用。真实 API 尚未连接；接入后在这里选择预先配置的模型。':'此 API 为界面示例，尚未连接。当前不会发送图片、消耗算力或调用远程模型。';document.querySelector('#generate-slice').disabled=!local;document.querySelector('#generate-slice').textContent=local?'✦ 生成 Slice':'API 尚未连接'};
const more=document.createElement('details');more.className='publish-more';more.innerHTML='<summary>发布信息与完整项目入口</summary><div class="publish-more-fields"></div>';const fields=document.querySelector('.publish-fields');for(const child of [...fields.children])if(child!==uploadFields)more.querySelector('div').append(child);fields.append(more);templateLabel.hidden=true;oldHelp.hidden=true;
let projectInfo=null,projectAuto='',customSlice='',customSliceName='',projectReadVersion=0,customReading=false;
const projectPanel=document.createElement('section');projectPanel.id='project-slice-panel';projectPanel.innerHTML=`<div class="project-source-heading"><strong>Feed 中展示哪个 Slice？</strong><p>完整项目与展示切片分开。轻量预览留在 Feed，大项目通过下方链接或桌面 App 继续。</p></div><div class="slice-source-picker"><label><input type="radio" name="projectSliceSource" value="auto" checked> 从上传内容生成</label><label><input type="radio" name="projectSliceSource" value="custom"> 使用自定义 Slice</label></div><p id="project-source-help">HTML 直接运行；文档提取实际内容；图片作为展示卡。不会自动理解或运行大型工程。</p><div id="custom-slice-area" hidden><label class="custom-slice-upload">上传自定义 Slice<input id="custom-slice-file" type="file" accept=".html,.htm"></label><small>单个自包含 HTML，最大 300 KB。可以是大项目中独立制作的试玩片段。</small><p id="custom-slice-status" role="status"></p></div><div class="project-local-note">本机预览支持 HTML / Markdown / TXT / JSON / 图片，最大 2 MB（HTML 300 KB）。暂不解析 ZIP、安装包或项目目录。完整项目请在「发布信息与完整项目入口」中填写链接。</div>`;
document.querySelector('#html-help').after(projectPanel);document.querySelector('#html-help').hidden=true;
function sourceMode(){return publishForm.querySelector('[name="projectSliceSource"]:checked').value}
function refreshProjectSource(){const custom=sourceMode()==='custom';document.querySelector('#custom-slice-area').hidden=!custom;fileAsset=custom?customSlice:projectAuto;fileName=custom?customSliceName:(projectInfo?.name||'');fileRevision++;updatePublishPreview(true)}
projectPanel.querySelectorAll('[name="projectSliceSource"]').forEach(r=>r.onchange=refreshProjectSource);
function projectPreviewHtml(title,text,image=''){return `<!doctype html><meta charset="UTF-8"><style>body{margin:0;font:15px system-ui;background:#edf1f4;color:#263441;line-height:1.8}img{width:100%;max-height:180px;object-fit:cover}main{padding:22px}small{font-size:10px;letter-spacing:1px;color:#748294}h2{font-size:22px;margin:10px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px system-ui}summary{cursor:pointer;padding:10px 0;color:#4e6579}</style>${image?`<img src="${image}" alt="上传的项目图片">`:''}<main><small>PROJECT SLICE / 文件内容预览</small><h2>${escapeHtml(title)}</h2><pre>${escapeHtml(text.slice(0,240))}</pre>${text.length>240?`<details><summary>展开更多内容 ↓</summary><pre>${escapeHtml(text.slice(240,1600))}</pre></details>`:''}</main>`}
const oldProjectImport=importFile;importFile=async function(file){if(creationMode!=='html')return oldProjectImport(file);if(!file)return;const revision=++projectReadVersion;readingFile=true;document.querySelector('#publish-error').textContent='';try{const ext=file.name.split('.').pop().toLowerCase();if(!['html','htm','md','txt','json','png','jpg','jpeg','webp'].includes(ext))throw Error('暂不支持此文件。请上传 HTML、文档或图片，或选择自定义 Slice。');if(!file.size||file.size>(['html','htm'].includes(ext)?307200:2097152))throw Error('文件为空或过大。HTML 最大 300 KB，其他支持的文件最大 2 MB。');let html,title=file.name.replace(/\.[^.]+$/,'').slice(0,50),text='';if(['png','jpg','jpeg','webp'].includes(ext)){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('图片格式不正确。');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('图片读取失败'));r.readAsDataURL(file)});const img=new Image();img.src=data;await img.decode();html=projectPreviewHtml(title,'上传的项目图片。打开完整项目以继续探索。',data)}else{text=await file.text();if(ext==='json')text=JSON.stringify(JSON.parse(text),null,2);html=['html','htm'].includes(ext)?text:projectPreviewHtml(title,text)}if(revision!==projectReadVersion||creationMode!=='html')return;projectInfo={name:file.name,size:file.size,type:ext};projectAuto=html;document.querySelector('#file-info').textContent='✓ '+file.name+' · 已读取实际文件内容';publishForm.elements.title.value=title;publishForm.elements.description.value=['html','htm'].includes(ext)?'试玩这个项目的交互片段。':text.trim().slice(0,160)||'从项目的一张图片开始探索。';refreshProjectSource()}catch(err){document.querySelector('#publish-error').textContent=err instanceof SyntaxError?'JSON 格式不正确，请检查文件后重试。':err.message;document.querySelector('#file-info').textContent=projectInfo?'仍使用：'+projectInfo.name:'尚未载入项目文件'}finally{readingFile=false}};
document.querySelector('#custom-slice-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;customReading=true;const revision=projectReadVersion;try{if(!/\.html?$/i.test(file.name)||!file.size||file.size>307200)throw Error('请选择不超过 300 KB 的自包含 HTML 文件。');const text=await file.text();if(!/<[a-z][\s\S]*>/i.test(text))throw Error('没有识别到 HTML 内容。');if(revision!==projectReadVersion||creationMode!=='html')return;customSlice=text;customSliceName=file.name;if(!publishForm.elements.title.value)publishForm.elements.title.value=file.name.replace(/\.[^.]+$/,'').slice(0,50);if(!publishForm.elements.description.value)publishForm.elements.description.value='试玩完整项目的一个交互片段。';document.querySelector('#custom-slice-status').textContent='✓ '+file.name;refreshProjectSource()}catch(err){document.querySelector('#custom-slice-status').textContent=err.message}finally{customReading=false}};
const simpleModeBefore=setCreationMode;setCreationMode=function(mode,clear=true){mode=mode==='template'?'image':mode;if(clear){projectReadVersion++;projectInfo=null;projectAuto='';customSlice='';customSliceName='';document.querySelector('#custom-slice-file').value='';document.querySelector('#custom-slice-status').textContent=''}simpleModeBefore(mode,clear);templateLabel.hidden=true;oldHelp.hidden=true;projectPanel.hidden=mode!=='html';document.querySelector('#html-help').hidden=true;if(mode==='html'){document.querySelector('#work-file').accept='.html,.htm,.md,.txt,.json,image/png,image/jpeg,image/webp';drop.querySelector('strong').textContent='上传项目文件（或下方自定义 Slice）';document.querySelector('#upload-hint').textContent='HTML / 文档 / 图片 · 读取内容生成展示片段'}};
const simpleDataBefore=formData;formData=function(){const d=simpleDataBefore();return {...d,computeModel:computeModel.value,...(creationMode==='html'?{projectInfo,projectAuto,customSlice,customSliceName,projectSliceSource:sourceMode()}:{} )}};
const simpleOpenBefore=openCreator;openCreator=function(work){simpleOpenBefore(work);const d=work||readStored(draftKey,null);computeModel.value=d?.computeModel||'local';computeModel.onchange();if(d?.projectInfo||d?.customSlice){projectInfo=d.projectInfo||null;projectAuto=d.projectAuto||'';customSlice=d.customSlice||'';customSliceName=d.customSliceName||'';publishForm.querySelector('[name="projectSliceSource"][value="'+(d.projectSliceSource==='custom'?'custom':'auto')+'"]').checked=true;setCreationMode('html',false);document.querySelector('#file-info').textContent=projectInfo?'已读取：'+projectInfo.name:'';document.querySelector('#custom-slice-status').textContent=customSliceName;refreshProjectSource()}else if(creationMode==='template')setCreationMode('image');projectPanel.hidden=creationMode!=='html';templateLabel.hidden=true;oldHelp.hidden=true;document.querySelector('#html-help').hidden=true;more.open=false};
const simpleSubmitBefore=publishForm.onsubmit;publishForm.onsubmit=e=>{if(creationMode==='html'&&(customReading||readingFile||!fileAsset)){e.preventDefault();document.querySelector('#publish-error').textContent=customReading||readingFile?'请等待文件读取完成。':sourceMode()==='custom'?'请上传自定义 Slice。':'请先上传项目文件。';return}if(creationMode==='image'&&computeModel.value!=='local'){e.preventDefault();document.querySelector('#publish-error').textContent='所选 API 尚未连接，请切换到本地演示后生成。';return}simpleSubmitBefore(e)};
setCreationMode(creationMode==='html'?'html':'image',false);
publishForm.addEventListener('invalid',e=>{if(more.contains(e.target))more.open=true},true);
